import{_ as l,o as i,c as a,ai as e}from"./chunks/framework.Ba-VnP44.js";const p=JSON.parse('{"title":"项目名称 — Agent 协作入口","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/agents.md","filePath":"ai/productivity/dev-spec/agents.md"}'),d={name:"ai/productivity/dev-spec/agents.md"};function r(n,t,s,o,h,g){return i(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="项目名称-—-agent-协作入口" tabindex="-1">项目名称 — Agent 协作入口 <a class="header-anchor" href="#项目名称-—-agent-协作入口" aria-label="Permalink to “项目名称 — Agent 协作入口”">​</a></h1><blockquote><p>通用项目级 AGENTS.md 模板 v1.0：只做入口、索引和协作约定，不承载详细开发规范。核心不是告诉 AI 怎么开发每一种软件，而是让 AI 进入任何一个项目，都能快速找到正确的规则、方法和项目资料。</p></blockquote><p>&lt;用一两句话介绍项目定位、主要用途，以及必要的关联仓库或系统。本文件是项目级 Agent 协作入口。&gt;</p><p><strong>协作定位：Rules 管约束，Skills 管方法，Agents 管角色与协作，Tools 提供外部能力；Agent 根据任务需要读取相关规则、调用适用 Skill。</strong></p><h2 id="协作原则-可迭代" tabindex="-1">协作原则（可迭代） <a class="header-anchor" href="#协作原则-可迭代" aria-label="Permalink to “协作原则（可迭代）”">​</a></h2><ul><li><strong>Rules</strong>：存放必须遵守的规则、限制和边界，不写操作教程，不重复详细开发规范。</li><li><strong>Skills</strong>：沉淀经过验证、可重复执行的工作流程、操作方法和验收标准。</li><li><strong>Agents</strong>：根据实际任务需要配置专业角色；简单任务由主 Agent 完成，复杂任务再考虑多 Agent 协作。</li><li><strong>MCP / Tools</strong>：提供外部系统、数据源和工具调用能力，按任务需要使用。</li><li><strong>Hooks / Scripts</strong>：处理适合自动化的检查、验证和重复操作。</li><li><strong>验收</strong>：以实际代码变更、任务验收标准、测试结果及必要的文档交付为依据。</li></ul><p>以上机制按项目实际情况逐步完善，不要求一次性全部配置。</p><h2 id="技术边界-摘要" tabindex="-1">技术边界（摘要） <a class="header-anchor" href="#技术边界-摘要" aria-label="Permalink to “技术边界（摘要）”">​</a></h2><ul><li>技术栈：&lt;填写主要技术栈&gt;</li><li>系统架构：&lt;填写核心架构或设计约束&gt;</li><li>数据存储：&lt;填写数据库及关键数据约束&gt;</li><li>关键约束：&lt;填写不可违反的技术或业务边界&gt;</li><li>详细规范：&lt;链接到对应开发规范文档&gt;</li></ul><p>涉及相关技术或业务修改时，优先查阅对应规范和 Skill，不得仅凭经验推断项目规则。</p><h2 id="skill-入口" tabindex="-1">Skill 入口 <a class="header-anchor" href="#skill-入口" aria-label="Permalink to “Skill 入口”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>Skill</th></tr></thead><tbody><tr><td>&lt;任务场景一&gt;</td><td>&lt;Skill 路径&gt;</td></tr><tr><td>&lt;任务场景二&gt;</td><td>&lt;Skill 路径&gt;</td></tr><tr><td>&lt;任务场景三&gt;</td><td>&lt;Skill 路径&gt;</td></tr></tbody></table><p>使用约定：</p><ul><li>根据当前任务选择适用 Skill，不强制加载无关 Skill。</li><li>Skill 与项目实际约束冲突时，以项目规则和已确认的业务要求为准。</li><li>新增可复用流程时，优先建立独立 Skill，并在本表登记。</li><li>已有 Skill 应持续验证和完善，避免重复创建。</li></ul><h2 id="关键文档" tabindex="-1">关键文档 <a class="header-anchor" href="#关键文档" aria-label="Permalink to “关键文档”">​</a></h2><ul><li>文档总览：&lt;文档路径&gt;</li><li>架构设计：&lt;文档路径&gt;</li><li>开发规范：&lt;文档路径&gt;</li><li>业务设计：&lt;文档路径&gt;</li><li>数据库设计：&lt;文档路径&gt;</li><li>部署运维：&lt;文档路径&gt;</li></ul><p>按任务需要读取相关文档，不要求每次执行任务都完整加载所有资料。</p><h2 id="提交与交付约定" tabindex="-1">提交与交付约定 <a class="header-anchor" href="#提交与交付约定" aria-label="Permalink to “提交与交付约定”">​</a></h2><ul><li>Git 提交说明：&lt;填写提交语言及格式要求&gt;</li><li>代码变更：限定在当前任务范围内，不擅自修改无关内容。</li><li>文档交付：明确正式文档、临时方案和过程记录的存放及提交规则。</li><li>数据库变更：明确 SQL、DDL、数据迁移脚本的存放和交付要求。</li><li>配置与敏感信息：不得将密码、密钥、令牌等敏感信息提交到代码仓库。</li><li>提交前检查：核对文件清单、代码变更、测试结果和无关文件。</li><li>高风险操作：涉及生产数据、生产部署、不可逆修改时，必须先获得用户明确授权。</li></ul><p>具体提交和交付要求以项目实际约定为准。</p><hr><p><strong>维护原则：本文件只维护项目入口、协作约定和必要索引。详细规则、执行方法、业务知识分别维护在 Rules、Skills 和项目文档中。随着项目发展，根据实际问题和重复工作持续迭代，不为追求完整而增加无用内容。</strong></p><h2 id="这份模板的固定与可变部分" tabindex="-1">这份模板的固定与可变部分 <a class="header-anchor" href="#这份模板的固定与可变部分" aria-label="Permalink to “这份模板的固定与可变部分”">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>通用模板</th><th>项目初始化时</th></tr></thead><tbody><tr><td>六个章节</td><td>固定</td><td>保留</td></tr><tr><td>协作原则</td><td>基本固定</td><td>根据工具能力调整</td></tr><tr><td>项目介绍</td><td>占位</td><td>必须填写</td></tr><tr><td>技术边界</td><td>占位</td><td>必须填写</td></tr><tr><td>Skill 入口</td><td>空白表格</td><td>按实际 Skill 填写</td></tr><tr><td>关键文档</td><td>占位</td><td>按实际文档填写</td></tr><tr><td>提交约定</td><td>基本固定</td><td>按项目要求调整</td></tr></tbody></table>',24)])])}const k=l(d,[["render",r]]);export{p as __pageData,k as default};
